// ?bfmeNotifyPlain@PathfindLayer@@AAEXXZ
// partial score=0.72 date=2026-09-27
// cl: /DNDEBUG /MD /EHsc

// BFME's bridge-less PathfindLayer reclassification pass.  PathfindLayer's
// field offsets are shared with the exact init, reset, apply-zone and
// setDestroyed bodies; setDestroyed reaches this body through ILT 0x0003A03F.

typedef int Int;

struct Coord3D
{
	float x;
	float y;
	float z;
};

struct ICoord2D
{
	Int x;
	Int y;
};

class PathfindCell
{
public:
	void reset();
	void setType(Int type);

	unsigned char m_pad00[0x0C];
	unsigned int m_unknown0C;
};

extern float g_bfmeDirectionWeight1285;

class PathfindLayer
{
private:
	void bfmeNotifyPlain();
	bool bfmeContainsPoint(const Coord3D *point);

	unsigned char m_pad00[4];
	PathfindCell **m_layerCells;       // +0x04
	Int m_width;                  // +0x08
	Int m_height;                 // +0x0C
	Int m_xOrigin;                // +0x10
	Int m_yOrigin;                // +0x14
	ICoord2D m_startCell;          // +0x18
	ICoord2D m_endCell;            // +0x20
	Int m_layer;                  // +0x28
};

// ?bfmeNotifyPlain@PathfindLayer@@AAEXXZ
void PathfindLayer::bfmeNotifyPlain()
{
	m_startCell.x = -1;
	m_startCell.y = -1;
	m_endCell.x = -1;
	m_endCell.y = -1;

	for (Int x = 0; x < m_width; ++x)
	{
		for (Int y = 0; y < m_height; ++y)
		{
			PathfindCell *cell = &m_layerCells[x][y];
			cell->m_unknown0C &= 0xFFFC0FFF;
			cell->m_unknown0C = cell->m_unknown0C ^
				((cell->m_unknown0C ^ (m_layer << 6)) & 0xFC0);

			Coord3D topLeft;
			topLeft.x = (x + m_xOrigin) * g_bfmeDirectionWeight1285;
			topLeft.y = (y + m_yOrigin) * g_bfmeDirectionWeight1285;
			Coord3D bottomRight;
			bottomRight.x = topLeft.x + g_bfmeDirectionWeight1285;
			bottomRight.y = topLeft.y + g_bfmeDirectionWeight1285;

			Int count = 0;
			if (bfmeContainsPoint(&topLeft))
				++count;
			Coord3D point = topLeft;
			point.y = bottomRight.y;
			if (bfmeContainsPoint(&point))
				++count;
			if (bfmeContainsPoint(&bottomRight))
				++count;
			point = topLeft;
			point.x = bottomRight.x;
			if (bfmeContainsPoint(&point))
				++count;

			cell->reset();
			cell->m_unknown0C = cell->m_unknown0C ^
				((cell->m_unknown0C ^ (m_layer << 6)) & 0xFC0);
			cell->setType(5);
			if (count > 0)
				cell->setType(0);
		}
	}
}
